fn swap3(a: &mut Vec<i32>, h: usize, i: usize, j: usize) {
    // Temporarily store the value at position h
    let temp = a[h];
    // Perform the 3‐cycle:
    // a[h] takes the original value of a[i],
    // a[i] takes the original value of a[j],
    // a[j] takes the original value of a[h] (stored in temp).
    a[h] = a[i];
    a[i] = a[j];
    a[j] = temp;
}

fn main() {
    let mut v = vec![10, 20, 30, 40, 50];
    // Cycle elements at positions 1, 3, 4:
    // original values: v[1]=20, v[3]=40, v[4]=50
    // after swap3: v[1]=40, v[3]=50, v[4]=20
    swap3(&mut v, 1, 3, 4);
    assert_eq!(v, vec![10, 40, 30, 50, 20]);
    println!("v after swap3: {:?}", v);
}